package nl.smartstreamlabs.sbwdroneconfig;
import net.minecraft.world.entity.*;import net.minecraft.world.level.*;import net.minecraft.world.phys.*;import net.minecraft.world.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.item.*;import net.minecraft.server.level.ServerPlayer;import net.minecraft.network.syncher.*;import net.minecraft.nbt.CompoundTag;import net.minecraft.network.chat.Component;import net.minecraft.util.Mth;import net.minecraft.core.BlockPos;import net.minecraft.tags.FluidTags;
/** Underwater forces plug into native SBW VehicleEntity travel/move, storage, health and OBB collision. */
public class Sd01Entity extends VatagEntity {
 private static final EntityDataAccessor<Boolean> LIGHT=SynchedEntityData.defineId(Sd01Entity.class,EntityDataSerializers.BOOLEAN),WET=SynchedEntityData.defineId(Sd01Entity.class,EntityDataSerializers.BOOLEAN);
 private static final EntityDataAccessor<Float> DEPTH=SynchedEntityData.defineId(Sd01Entity.class,EntityDataSerializers.FLOAT),FIN=SynchedEntityData.defineId(Sd01Entity.class,EntityDataSerializers.FLOAT),SPEED=SynchedEntityData.defineId(Sd01Entity.class,EntityDataSerializers.FLOAT);
 private static final EntityDataAccessor<String> SONAR=SynchedEntityData.defineId(Sd01Entity.class,EntityDataSerializers.STRING);
 private static final EntityDataAccessor<Long> PULSE=SynchedEntityData.defineId(Sd01Entity.class,EntityDataSerializers.LONG),NEXT_SONAR=SynchedEntityData.defineId(Sd01Entity.class,EntityDataSerializers.LONG);
 private Vec3 lastMotionPosition;private int keys;private long lastInput,nextSonar,nextLamp;private double holdY=Double.NaN;private float yawRate,wantedYaw,wantedPitch,oldFin,fin;private boolean hadPower,verticalWas,settled,suppressDrops;
 public Sd01Entity(EntityType<? extends Sd01Entity> type,Level level){super(type,level);}
 @Override protected void defineSynchedData(){super.defineSynchedData();entityData.define(LIGHT,false);entityData.define(WET,false);entityData.define(DEPTH,Float.NaN);entityData.define(FIN,0f);entityData.define(SPEED,0f);entityData.define(SONAR,"");entityData.define(PULSE,-1000L);entityData.define(NEXT_SONAR,0L);}
 public boolean lights(){return entityData.get(LIGHT);}public boolean submerged(){return entityData.get(WET);}public float depth(){return entityData.get(DEPTH);}public float fin(float p){return Mth.lerp(p,oldFin,fin);}public String sonar(){return entityData.get(SONAR);}public float telemetrySpeed(){return entityData.get(SPEED);}public long pulse(){return entityData.get(PULSE);}public long sonarWait(){return Math.max(0,entityData.get(NEXT_SONAR)-level().getGameTime());}
 @Override public boolean canAddPassenger(Entity e){return false;}
 @Override protected boolean remoteFireAllowed(){return false;}
 @Override public boolean canPlaceItem(int slot,ItemStack stack){return false;}
 @Override public void input(ServerPlayer p,int flags,float yaw,float pitch){if(p!=operator()||!Float.isFinite(yaw)||!Float.isFinite(pitch))return;super.input(p,0,yaw,pitch);keys=flags&127;lastInput=level().getGameTime();wantedYaw=yaw;wantedPitch=pitch;}
 @Override public void loadingHeartbeat(ServerPlayer p){super.loadingHeartbeat(p);if(operator()==p){keys=0;lastInput=level().getGameTime();}}
 @Override public boolean takeControl(ServerPlayer p){if(getEnergy()<=0||!link(p)||!super.takeControl(p))return false;lastInput=level().getGameTime();holdY=getY();keys=0;var d=cameraFrame(1).transformDirection(new org.joml.Vector3d(0,0,1)).normalize();wantedYaw=(float)Math.toDegrees(-Math.atan2(d.x,d.z));wantedPitch=(float)-Math.toDegrees(Math.asin(d.y));super.input(p,0,wantedYaw,wantedPitch);return true;}
 @Override public void releaseControl(){super.releaseControl();keys=0;yawRate=0;verticalWas=false;holdY=getY();}
 public static double radio(){return Math.min(AddonConfig.droneMaxRange(),Sd01Config.RANGE.get())*Sd01Config.WATER_RANGE.get();}
 public boolean link(ServerPlayer p){return p.level()==level()&&p.distanceToSqr(this)<=radio()*radio()&&(!Sd01Config.JAMMERS.get()||!DroneJamStateManager.isHardJammed(this));}
 /** No native surface-boat engine and no client physics. SBW applies gravity once after this hook. */
 @Override public void travel(){if(level().isClientSide)return;
  boolean wet=Sd01Hull.waterPose(this,position(),getYRot(),getXRot());entityData.set(WET,wet);if(!Double.isFinite(holdY))holdY=getY();
  boolean live=operator()!=null&&operator().isAlive()&&!operator().hasDisconnected()&&level().getGameTime()-lastInput<=20&&link(operator());
  if(!live&&operator()!=null)VatagSessions.stop(operator());boolean powered=getEnergy()>0&&!isWreck();if(powered&&!hadPower)holdY=getY();hadPower=powered;Vec3 v=getDeltaMovement();double targetY=0,targetSpeed=0;int vertical=0,steer=0;
  if(wet){
   if(live&&powered){vertical=((keys&64)!=0?1:0)-((keys&16)!=0?1:0);int drive=((keys&1)!=0?1:0)-((keys&2)!=0?1:0);steer=((keys&8)!=0?1:0)-((keys&4)!=0?1:0);if((keys&32)!=0){drive=steer=vertical=0;}targetSpeed=drive>0?Sd01Config.FORWARD.get():drive<0?-Sd01Config.REVERSE.get():0;}
   if(vertical!=0){targetY=vertical*Sd01Config.VERTICAL.get();holdY=getY();}else{
    if(verticalWas)holdY=getY();var mode=!powered?Sd01Config.EMPTY.get():!live?Sd01Config.LOST.get():Sd01Config.FailSafe.HOLD;
    if(mode==Sd01Config.FailSafe.SURFACE)targetY=powered?.035:.012;else if(mode==Sd01Config.FailSafe.SINK||!powered)targetY=-.012;else targetY=Mth.clamp((holdY-getY())*.12-v.y*.6,-Sd01Config.VERTICAL.get(),Sd01Config.VERTICAL.get());
   }verticalWas=vertical!=0;
   double heading=-getYRot()*Math.PI/180;Vec3 forward=new Vec3(Math.sin(heading),0,Math.cos(heading));double speed=v.dot(forward),side=v.x*forward.z-v.z*forward.x;double acceleration=targetSpeed==0?.025:Sd01Config.ACCEL.get();speed=Mth.approach((float)speed,(float)targetSpeed,(float)acceleration);side*=.60;double vy=Mth.approach((float)v.y,(float)targetY,vertical==0?.025f:.014f);v=new Vec3(forward.x*speed+forward.z*side,vy,forward.z*speed-forward.x*side);if(v.horizontalDistanceSqr()<1e-7)v=new Vec3(0,v.y,0);
   yawRate=Mth.approach(yawRate,(float)(steer*Sd01Config.TURN.get()),.25f);float nextYaw=getYRot()+yawRate;float targetPitch=(float)Mth.clamp(Math.toDegrees(Math.atan2(-v.y,Math.max(.12,v.horizontalDistance()))),-18,18);float nextPitch=Mth.approachDegrees(getXRot(),targetPitch,.55f);
   boolean rotation=true;int steps=(int)Math.ceil(Math.max(Math.abs(nextYaw-getYRot()),Math.abs(nextPitch-getXRot()))/.75);for(int i=1;i<=steps;i++){float t=i/(float)steps,yr=Mth.lerp(t,getYRot(),nextYaw),pr=Mth.lerp(t,getXRot(),nextPitch);if(!Sd01Hull.free(this,position(),yr,pr)||!Sd01Hull.waterPose(this,position(),yr,pr)){rotation=false;break;}}
   if(rotation){setYRot(nextYaw);setXRot(nextPitch);}else yawRate=0;setZRot(0);updateOBB();
   float wantedFin=(float)Mth.clamp(-v.y*.8+(getXRot()-targetPitch)*.002,-.10,.10);entityData.set(FIN,Mth.approach(entityData.get(FIN),wantedFin,.008f));
   // Neutral buoyancy cancels only the native SBW gravity that is applied later in this tick.
   setDeltaMovement(v.add(0,computed().getGravity(),0));
  }else {keys=0;yawRate=0;holdY=getY();setDeltaMovement(v.multiply(.5,1,.5));entityData.set(FIN,0f);}
  if(live){var a=VatagAim.local(getVehicleTransform(1),wantedYaw,wantedPitch);float rate=Sd01Config.LOOK.get().floatValue();setTurretYRot(Mth.approachDegrees(getTurretYRot(),Mth.clamp(a.x,-65,65),rate));setTurretXRot(Mth.approach(getTurretXRot(),Mth.clamp(a.y,-45,45),rate));}
  setForwardInputDown(false);setBackInputDown(false);setLeftInputDown(false);setRightInputDown(false);setFireInputDown(false);setPower((float)(targetSpeed/Sd01Config.FORWARD.get()));
 }
 @Override public void move(MoverType type,Vec3 movement){if(level().isClientSide&&type==MoverType.SELF)return;if(!level().isClientSide&&type==MoverType.SELF){Vec3 safe=Sd01Hull.swept(this,movement,submerged());if(safe.subtract(movement).lengthSqr()>1e-8)setDeltaMovement(safe.scale(.5));super.move(type,safe);return;}super.move(type,movement);}
 @Override public void baseTick(){super.baseTick();if(level().isClientSide){oldFin=fin;fin=Mth.lerp(.25f,fin,entityData.get(FIN));return;}if(tickCount%4==0&&lastMotionPosition!=null){double distance=position().distanceTo(lastMotionPosition);entityData.set(SPEED,distance<4?(float)(Math.round(distance*500)/100d):0f);}if(tickCount%4==0)lastMotionPosition=position();if(tickCount%20==0){if(getEnergy()>0&&submerged()){int cost=getDeltaMovement().lengthSqr()>.0001?Sd01Config.DRIVE_COST.get():Sd01Config.HOLD_COST.get();consumeEnergy(cost+(lights()?Sd01Config.LIGHT_COST.get():0));}updateDepth();}if(lights()&&(getEnergy()<=0||isWreck()))entityData.set(LIGHT,false);Sd01Lights.tick(this);}
 private void updateDepth(){var pos=blockPosition();float depth=Float.NaN;for(int i=0;i<Sd01Config.DEPTH_SCAN.get()&&pos.getY()<level().getMaxBuildHeight()-1;i++,pos=pos.above()){if(!level().hasChunkAt(pos))break;var f=level().getFluidState(pos);if(!f.is(FluidTags.WATER))break;var next=pos.above();if(!level().getFluidState(next).is(FluidTags.WATER)){if(level().getBlockState(next).isAir())depth=(float)Math.max(0,pos.getY()+f.getHeight(level(),pos)-getY());break;}}entityData.set(DEPTH,depth);}
 public boolean command(ServerPlayer p,boolean lamp){if(operator()!=p||!VatagSessions.controlling(p,this)||getEnergy()<=0||!link(p))return false;if(lamp){long now=level().getGameTime();if(now<nextLamp||!AddonConfig.enableSpotlightModule()||!AddonConfig.spotlightRealLightEnabled())return false;nextLamp=now+6;entityData.set(LIGHT,!lights());Sd01Lights.tick(this);return true;}long t=level().getGameTime();if(t<nextSonar||!submerged()||getEnergy()<Sd01Config.SONAR_COST.get())return false;consumeEnergy(Sd01Config.SONAR_COST.get());nextSonar=t+Sd01Config.SONAR_COOLDOWN.get();entityData.set(NEXT_SONAR,nextSonar);entityData.set(SONAR,Sd01Sonar.scan(this));entityData.set(PULSE,t);return true;}
 public org.joml.Matrix4d cameraFrame(float p){return new org.joml.Matrix4d(getVehicleTransform(p)).translate(0,.11,3.78).rotateY(Mth.rotLerp(p,getTurretYRotO(),getTurretYRot())*Mth.DEG_TO_RAD).rotateX(Mth.lerp(p,getTurretXRotO(),getTurretXRot())*Mth.DEG_TO_RAD);}
 @Override public Vec3 camera(boolean aim,float p){var v=cameraFrame(p).transformPosition(new org.joml.Vector3d());return new Vec3(v.x,v.y,v.z);}
 public void lamps(boolean on){if(!level().isClientSide)entityData.set(LIGHT,on&&getEnergy()>0);}
 @Override public void setYRot(float yaw){super.setYRot(yaw);setBoundingBox(makeBoundingBox());}
 @Override public void setXRot(float pitch){super.setXRot(pitch);setBoundingBox(makeBoundingBox());}
 @Override protected AABB makeBoundingBox(){return Sd01Hull.bounds(position(),getYRot(),getXRot());}
 @Override public AABB getBoundingBoxForCulling(){return makeBoundingBox().inflate(.25);}
 public boolean pack(ServerPlayer p){if(settled||!permitted(p)||operator()!=null||getDeltaMovement().lengthSqr()>.0004)return false;var data=new CompoundTag();saveWithoutId(data);for(String k:new String[]{"UUID","Pos","Motion","Rotation","Passengers"})data.remove(k);var item=com.atsuishio.superbwarfare.item.container.ContainerBlockItem.createInstance(this);if(!p.getInventory().add(item)&&p.drop(item,false)==null)return false;settled=true;discard();return true;}
 private boolean recharge(ServerPlayer p,ItemStack stack){if(!permitted(p)||operator()!=null||!SbwCompat.isSbwBattery(stack))return false;int missing=Math.max(0,getMaxEnergy()-getEnergy());int n=stack.getCapability(net.minecraftforge.common.capabilities.ForgeCapabilities.ENERGY).map(s->s.extractEnergy(Math.min(missing,AddonConfig.batteryTransferRate()),false)).orElse(0);if(n>0)setEnergy(getEnergy()+n);p.displayClientMessage(Component.translatable(n>0?"sd01.charged":"sd01.battery",n),true);return true;}
 @Override public InteractionResult interact(Player p,InteractionHand hand){if(settled||isRemoved())return InteractionResult.FAIL;var held=p.getItemInHand(hand);if(p instanceof ServerPlayer sp){if(!permitted(sp))return InteractionResult.FAIL;if(p.isShiftKeyDown()&&held.is(com.atsuishio.superbwarfare.init.ModTags.Items.TOOLS_CROWBAR))return pack(sp)?InteractionResult.CONSUME:InteractionResult.FAIL;if(SbwCompat.isSbwBattery(held))return recharge(sp,held)?InteractionResult.CONSUME:InteractionResult.FAIL;if(SbwCompat.isMonitor(held)){claimOwner(sp);SbwCompat.ensureDroneOwner(this,sp);var r=super.interact(p,hand);mark(held,true);return r;}}return held.isEmpty()?InteractionResult.PASS:super.interact(p,hand);}
 public static boolean monitor(ItemStack stack){return stack.hasTag()&&stack.getTag().getBoolean("SD01SubmarineMonitor");}public static void mark(ItemStack stack,boolean value){stack.getOrCreateTag().putBoolean("SD01SubmarineMonitor",value);}
 @Override public void destroy(){if(level().isClientSide||isRemoved())return;Sk01Deaths.destroyed(this);settled=true;if(operator()!=null)VatagSessions.stop(operator());discard();}
 @Override public void remove(RemovalReason why){if(isRemoved())return;if(!level().isClientSide){if(operator()!=null)VatagSessions.stop(operator());Sd01Lights.clear(this);ChunkTicketManager.releaseDrone(this);}suppressDrops=true;try{super.remove(why);}finally{suppressDrops=false;}}
 @Override public net.minecraft.world.entity.item.ItemEntity spawnAtLocation(ItemStack s,float offset){return suppressDrops?null:super.spawnAtLocation(s,offset);}
 @Override public void addAdditionalSaveData(CompoundTag n){super.addAdditionalSaveData(n);n.putBoolean("Sd01Lamps",lights());n.putDouble("Sd01HoldY",Double.isFinite(holdY)?holdY:getY());n.putLong("Sd01SonarWait",Math.max(0,nextSonar-level().getGameTime()));}
 @Override public void readAdditionalSaveData(CompoundTag n){super.readAdditionalSaveData(n);entityData.set(LIGHT,n.getBoolean("Sd01Lamps"));holdY=n.contains("Sd01HoldY")?n.getDouble("Sd01HoldY"):getY();nextSonar=level().getGameTime()+Math.min(Sd01Config.SONAR_COOLDOWN.get(),n.getLong("Sd01SonarWait"));entityData.set(NEXT_SONAR,nextSonar);settled=false;keys=0;}
}
